        balance = 0
        for x in sequence:
            balance += x if x >= 0 else abs(x)
            if balance < 0:
                return False
        return balance == 0

    result = []
    for i in range(n):
        a, b, idx = same_front_back[i % len(same_front_back)]
        result.append((a, b))

    if result:
        return "NO\n"

    result = []
    for card in diff_front_back:
