def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = lines[1:n+1]

    # Convert to list of lists for easier access
    chars = [list(line) for line in grid]

    # Precompute row masks
    # row_mask[i][c] = XOR mask of characters with odd frequencies in row i, columns 0..c
    row_mask = [[0] * m for _ in range(n)]
    for i in range(n):
        mask = 0
        for j in range(m):
            mask ^= (1 << (ord(chars[i][j]) - ord('a')))
            row_mask[i][j] = mask

    # Precompute column masks
    # col_mask[c][r] = XOR mask of characters with odd frequencies in column c, rows 0..r
    col_mask = [[0] * n for _ in range(m)]
    for j in range(m):
        mask = 0
        for i in range(n):
            mask ^= (1 << (ord(chars[i][j]) - ord('a')))
            col_mask[j][i] = mask

    count = 0
    for i1 in range(n):
        for i2 in range(i1, n):
            for j1 in range(m):
                for j2 in range(j1, m):
                    # Check row condition
                    row_ok = True
                    for i in range(i1, i2 + 1):
                        mask = row_mask[i][j2]
                        if j1 > 0:
                            mask ^= row_mask[i][j1 - 1]
                        if bin(mask).count('1') > 1:
                            row_ok = False
                            break

                    if not row_ok:
                        continue

                    # Check column condition
                    col_ok = True
                    for j in range(j1, j2 + 1):
                        mask = col_mask[j][i2]
                        if i1 > 0:
                            mask ^= col_mask[j][i1 - 1]
                        if bin(mask).count('1') > 1:
                            col_ok = False
                            break

                    if col_ok:
                        count += 1

    return str(count) + '\n'


