import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        coords = list(map(float, lines[i].split()))
        points.append(coords)

    def dist2(p1, p2):
        return (p1[0]-p2[0])**2 + (p1[1]-p2[1])**2 + (p1[2]-p2[2])**2

    def solve(points_on_boundary, all_points):
        """Find smallest enclosing sphere. Recursive Welzl's algorithm."""
        if len(points_on_boundary) == 4:
            return sphere_from_4points(points_on_boundary)
        if len(all_points) == 0:
            return [0.0, 0.0, 0.0], 0.0

        pivot = all_points[0]
        rest = all_points[1:]

        S = solve(points_on_boundary, rest)
        center, radius = S

        if dist2(center, pivot) <= radius + 1e-9:
            return S

        newS = solve(points_on_boundary + [pivot], rest)
        return newS

    def sphere_from_0points():
        return [0.0, 0.0, 0.0], 0.0

    def sphere_from_1point(p):
        return list(p), 0.0

    def sphere_from_2points(p1, p2):
        d = math.sqrt(dist2(p1, p2))
        if d < 1e-9:
            return p1, 0.0
        cx = (p1[0] + p2[0]) / 2
        cy = (p1[1] + p2[1]) / 2
        cz = (p1[2] + p2[2]) / 2
        return [cx, cy, cz], d / 2

    def sphere_from_3points(p1, p2, p3):
        # Solve for circumcircle of 3 points by finding intersection of two bisecting planes
        # Use linear algebra: 2*(p2-p1)·c = |p2|^2-|p1|^2 and 2*(p3-p1)·c = |p3|^2-|p1|^2
        # Add cross product vector as constraint

        v1 = [p2[0]-p1[0], p2[1]-p1[1], p2[2]-p1[2]]
        v2 = [p3[0]-p1[0], p3[1]-p1[1], p3[2]-p1[2]]
        cross = [v1[1]*v2[2] - v1[2]*v2[1], v1[2]*v2[0] - v1[0]*v2[2], v1[0]*v2[1] - v1[1]*v2[0]]

        b1 = (p2[0]**2 - p1[0]**2) + (p2[1]**2 - p1[1]**2) + (p2[2]**2 - p1[2]**2)
        b2 = (p3[0]**2 - p1[0]**2) + (p3[1]**2 - p1[1]**2) + (p3[2]**2 - p1[2]**2)

        # Build matrix [v1, v2, cross]
        M = [v1, v2, cross]
        B = [b1/2.0, b2/2.0, 0.0]  # Third equation ensures c is at right place

        c = gauss3x3(M, B)
        if c is None:
            return sphere_from_2points(p1, p2)

        cnt = [p[0] for p in c]
        cnt.append(c[1][0])

        return cnt, math.sqrt(dist2(cnt[0], cnt[1]))

    def gauss3x3(M, B):
        # Simple Gaussian elimination
        for i in range(3):
            # Find pivot
            maxrow = i
            for k in range(i+1, 3):
                if abs(M[k][i]) > abs(M[maxrow][i]):
                    maxrow = k
            M[i], M[maxrow] = M[maxrow], M[i]
            B[i], B[maxrow] = B[maxrow], B[i]

            if abs(M[i][i]) < 1e-12:
                return None
            for j in range(i+1, 3):
                if abs(M[j][i]) > 1e-12:
                    div = M[j][i] / M[i][i]
                    for k in range(i, 3):
                        M[j][k] -= div * M[i][k]
                    B[j] -= div * B[i]

        x = [B[i] / M[i][i] for i in range(3)]
        return x

    def sphere_from_4points(a, b, c, d):
        # Solve so center is equidistant from all four points
        # This forms a system of 3 linear equations from pair differences
        # Example: |c-a|^2 = |c-b|^2, |c-a|^2 = |c-c|^2, |c-a|^2 = |c-d|^2
        B = [
            (b[0]**2 - a[0]**2) + (b[1]**2 - a[1]**2) + (b[2]**2 - a[2]**2),
            (c[0]**2 - a[0]**2) + (c[1]**2 - a[1]**2) + (c[2]**2 - a[2]**2),
            (d[0]**2 - a[0]**2) + (d[1]**2 - a[1]**2) + (d[2]**2 - a[2]**2)
        ]

        M = [
            [2*(b[0]-a[0]), 2*(b[1]-a[1]), 2*(b[2]-a[2])],
            [2*(c[0]-a[0]), 2*(c[1]-a[1]), 2*(c[2]-a[2])],
            [2*(d[0]-a[0]), 2*(d[1]-a[1]), 2*(d[2]-a[2])]
        ]

        c = gauss3x3(M, B)
        if c is None:
            # Fall back to sphere from 3 points (coplanar)
            if len(set([dist2(a,b), dist2(b,c), dist2(a,c), dist2(a,d), dist2(b,d), dist2(c,d)])) < 4:
                return sphere_from_3points(a, b, c)
            else:
                # Degenerate, use 2 points
                if dist2(a,b) > dist2(a,c) and dist2(a,b) > dist2(a,d) and dist2(a,b) > dist2(b,c):
                    return sphere_from_2points(a, b)
                elif dist2(a,c) > dist2(a,b) and dist2(a,c) > dist2(a,d):
                    return sphere_from_2points(a, c)
                elif dist2(b,c) > dist2(b,a) and dist2(b,c) > dist2(b,d):
                    return sphere_from_2points(b, c)
                else:
                    return sphere_from_2points(a, d)

        center = [c[0], c[1], c[2]]
        radius = math.sqrt(dist2(center, a))
        return center, radius

    # Run Welzl's algorithm
    center, _ = solve([], points)

    return f"{center[0]:.10f} {center[1]:.10f} {center[2]:.10f}"
