        if x == 1:
            return 1
        rem = x % 3
        if k == 1:
            if rem == 0 or rem == 1:
                return 0
            return 1
        base = x % 10 if k % 2 == 1 else x % 3

        if rem == 0:  # even: 2x
            return (base)
        else:  # odd: 2x+1
            return 0 if base % 2 == 1 else 1

    xor_sum = 0
    for val in a:
