    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(1, m + 1):
        line = lines[i]
        if not line:
            continue
        u, v = map(int, line.split())
        adj[u].append(v)
        edges.append((u, v))

    # Compute all-pairs shortest paths using BFS from each city
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist[i][i] = 0
        q = deque([i])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[i][v] == float('inf'):
                    dist[i][v] = dist[i][u] + 1
                    q.append(v)

    # Find optimal sequence of 4 distinct cities
    max_total = -1
    best_order = []

    # For all permutations of 4 cities
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j or dist[i][j] == float('inf'):
                continue
            for k in range(1, n + 1):
                if k in (i, j) or dist[j][k] == float('inf'):
                    continue
                for l in range(1, n + 1):
                    if l in (i, j, k) or dist[k][l] == float('inf'):
                        continue

                    total = dist[i][j] + dist[j][k] + dist[k][l]
                    if total > max_total:
                        max_total = total
                        best_order = (i, j, k, l)

    return ' '.join(map(str, best_order))
