from collections import defaultdict

def solution(input_string):
    lines = input_string.strip().split('\n')
    if len(lines) < 2:
        return '0\n'

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    edges = []
    for i in range(2, 2 + m):
        if i < len(lines) and lines[i]:
            parts = lines[i].split()
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                edges.append((u, v))

    # Find all prime factors for each position
    prime_to_indices = defaultdict(set)

    for idx, num in enumerate(a):
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                prime_to_indices[d].add(idx + 1)  # Store 1-indexed position
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            prime_to_indices[temp].add(idx + 1)

    total_ops = 0

    for prime, indices in prime_to_indices.items():
        if len(indices) < 2:
            continue

        # Build bipartite graph for this prime
        # Left side: odd positions (1-indexed odd numbers: 1, 3, 5, ...)
        # Right side: even positions (1-indexed even numbers: 2, 4, 6, ...)
        adj = defaultdict(list)

        for u, v in edges:
            if (u in indices and v in indices):
                if u % 2 == 1:  # u is odd position (left side)
                    adj[u].append(v)
                else:  # v is odd position (left side)
                    adj[v].append(u)

        # Max bipartite matching using DFS
        match = {}  # match[right_node -> left_node]
        vis = set()

        def dfs(u):
            for v in adj[u]:
                if v not in vis:
                    vis.add(v)
                    if v not in match:
                        match[v] = u
                        return True
                    else:
                        if dfs(match[v]):
                            match[v] = u
                            return True
            return False

        count = 0
        for idx in indices:
            if idx % 2 == 1:  # Only try from left side
                vis.clear()
                if dfs(idx):
                    count += 1

        total_ops += count

    return str(total_ops) + '\n'
