        idx += n

        axis_count = 0
        diagonal_count = 0

        # Check axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    if is_axis_aligned_square(matrix, r, c, size):
                        axis_count += 1

        # Check diagonal squares
        for cr in range(n):
            for cc in range(m):
                max_r = min(cr, n - 1 - cr, cc, m - 1 - cc)
                for r in range(1, max_r + 1):
                    if is_diagonal_square(matrix, cr, cc, r):
                        diagonal_count += 1

        results.append(str(axis_count + diagonal_count))

    return '\n'.join(results)


def is_axis_aligned_square(matrix, r, c, size):
    """Check if there's an axis-aligned square frame at (r,c) with given size."""
    n, m = len(matrix), len(matrix[0])

    # Check top border
    for j in range(size):
        if matrix[r][c + j] != '1':
            return False

    # Check bottom border
    for j in range(size):
        if matrix[r + size - 1][c + j] != '1':
            return False

    # Check left border (excluding corners)
    for i in range(1, size - 1):
        if matrix[r + i][c] != '1':
            return False

    # Check right border (excluding corners)
    for i in range(1, size - 1):
        if matrix[r + i][c + size - 1] != '1':
            return False

    # Check interior is all 0
    for i in range(1, size - 1):
        for j in range(1, size - 1):
            if matrix[r + i][c + j] != '0':
                return False

    # Check no foreign 1 touches the frame (8 neighbors of each border cell)
    for i in range(r - 1, r + size):
        for j in range(c - 1, c + size):
            if 0 <= i < n and 0 <= j < m:
                if matrix[i][j] == '1':
                    # If this 1 is on border, it's part of frame
                    if (i == r or i == r + size - 1 or j == c or j == c + size - 1):
                        continue
                    # Otherwise, it's a foreign 1 touching the frame
                    return False

    return True


def is_diagonal_square(matrix, cr, cc, r):
    """Check if there's a diagonal square frame centered at (cr,cc) with radius r."""
    n, m = len(matrix), len(matrix[0])

    # Interior (center) must be 0 for r >= 1
    if matrix[cr][cc] != '0':
        return False

    # All border cells (Manhattan distance = r) must be '1'
    for row in range(cr - r, cr + r + 1):
        for col in range(cc - r, cc + r + 1):
            if abs(row - cr) + abs(col - cc) == r:
                if matrix[row][col] != '1':
                    return False

    # All interior cells (Manhattan distance < r) must be '0'
    for row in range(cr - r + 1, cr + r):
        for col in range(cc - r + 1, cc + r):
            if abs(row - cr) + abs(col - cc) < r:
                if matrix[row][col] != '0':
                    return False

    # Check no foreign 1 touches the frame (8 neighbors of each border cell)
    for row in range(cr - r - 1, cr + r + 2):
        for col in range(cc - r - 1, cc + r + 2):
            if 0 <= row < n and 0 <= col < m:
                if matrix[row][col] == '1':
                    # Check if this 1 is actually touching any border cell
                    min_dist = float('inf')
                    touches = False
                    for dr in range(-1, 2):
                        for dc in range(-1, 2):
                            nr, nc = row - (cr - r) + dr, col - (cc - r) + dc
                            if abs(nr - cr) + abs(nc - cc) == r:
                                if 0 <= nr < n and 0 <= nc < m:
                                    touches = True
                                    break
                        if touches:
                            break
                    if not touches and abs(row - cr) + abs(col - cc) <= r:
                        return False

    return True
