    for i in range(n):
        for j in range(m):
            row_parity = i % 2
            col_parity = j % 2

            if row_parity == 0:
                if col_parity == 0:
                    expected_colors[(i, j)] = major_seq[j % 4]
                else:
                    expected_colors[(i, j)] = minor_seq[j % 4]
            else:
                if col_parity == 0:
                    expected_colors[(i, j)] = minor_seq[j % 4]
                else:
                    expected_colors[(i, j)] = major_seq[j % 4]

    # Check pre-filled cells
    for i in range(n):
        for j in range(m):
            if grid[i][j] != '0':
                c = int(grid[i][j])
                if (i, j) not in expected_colors:
                    return '0'
                color = expected_colors[(i, j)]
                if color != c:
                    return '0'

