Looking at this problem, I need to:
1. Validate that existing pipes don't already leak
2. For each empty cell, count how many pipe types (1-4) can validly be placed without causing leaks
3. Multiply these counts modulo 1000003

A pipe leaks if an end points to either an empty cell or a non-matching pipe end. At the grid border, an end is valid (connects to border).

```python
MOD = 1000003

def solution(grid_str):
    lines = grid_str.strip().split('\n')
    if len(lines) < 2:
        return "0\n"

    first_line = lines[0]
    if not first_line:
        return "0\n"

    n, m = map(int, first_line.split())

    grid = []
    for i in range(1, n + 1):
        if i < len(lines):
            grid.append(list(lines[i]))
        else:
            grid.append(['.'] * m)

    # Type mapping: [top, left, bottom, right]
    type_end_map = {
        '1': [True, True, False, False],   # top and left
        '2': [True, False, False, True],   # top and right
        '3': [False, True, True, False],   # left and bottom
        '4': [False, False, True, True]    # bottom and right
    }

    # Direction vector [top, left, bottom, right]
    direction = [(-1, 0), (0, -1), (1, 0), (0, 1)]

    def count_valid_for_cell(r, c):
        """Count the number of valid pipe types for empty cell at (r,c)"""
        if grid[r][c] != '.':
            return 1

        valid_count = 0
        for ctype in ['1', '2', '3', '4']:
            ends = type_end_map[ctype]
            is_valid = True

            for i in range(4):
                if ends[i]:
                    dr, dc = direction[i]
                    nr, nc = r + dr, c + dc

                    # Check if this direction is at the border
                    if nr < 0 or nr >= n or nc < 0 or nc >= m:
                        # End is at border - valid
                        continue

                    neighbor = grid[nr][nc]
                    if neighbor == '.':
                        # No pipe to connect to, but we have an end -> leaks
                        is_valid = False
                        break

                    # Check if neighbor can connect back
                    # Opposite direction index: (i + 2) % 4
                    if not type_end_map[neighbor][(i + 2) % 4]:
                        is_valid = False
                        break

            if is_valid:
                valid_count += 1

        return valid_count

    def is_pre_filled_leaking(r, c):
        """Check if an existing pipe at (r,c) has any leak"""
        ctype = grid[r][c]
        if ctype == '.':
            return False

        ends = type_end_map[ctype]

        for i in range(4):
            if ends[i]:
                dr, dc = direction[i]
                nr, nc = r + dr, c + dc

                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    # At border - valid connection
                    continue

                neighbor = grid[nr][nc]
                if neighbor != '.':
                    # Check if neighbor has opposite end
                    if not type_end_map[neighbor][(i + 2) % 4]:
                        return True

        return False

    ans = 1
    for r in range(n):
        for c in range(m):
            cell = grid[r][c]
            if cell == '.':
                valid = count_valid_for_cell(r, c)
                if valid == 0:
                    return "0\n"
                ans = (ans * valid) % MOD
            else:
                if is_pre_filled_leaking(r, c):
                    return "0\n"

    return str(ans) + '\n'
```

