def solve_for_match(a, b):
    # Outcomes in order of preference (best score first)
    outcomes = [
        (3, 0),  # Try 3:0 first
        (3, 1),  # Then 3:1
        (3, 2),  # Then 3:2
        (1, 2),  # Then 1:2
        (2, 3),  # Then 2:3
        (0, 3)   # Finally 0:3
    ]

    for wA, wB in outcomes:
        total_sets = wA + wB
        if total_sets > 5:
            continue

        sets_list = find_valid_sets(a, b, wA, wB, total_sets)
        if sets_list is not None:
            return f"{wA}:{wB}\n" + " ".join(f"{x}:{y}" for x, y in sets_list) + " "

    return "Impossible"


def is_valid_winner(x, y, is_fifth):
    """Check if x won the set (target is 25 or 15 based on is_fifth)"""
    target = 15 if is_fifth else 25
    return x >= target and (x - y) >= 2


def is_valid_5th_winner(x, y):
    """Check if x won the 5th set"""
    return x >= 15 and (x - y) >= 2 or y >= 15 and (y - x) >= 2


def find_valid_sets(a, b, wA, wB, total_sets):
    """
    Use DP to find valid set sequences.
    Returns list of (A_points, B_points) or None if impossible.
    """
    # Parse out remaining wins needed for each team
    remaining_a = wA
    remaining_b = wB

    # dp[state) returns list of valid set scores to reach that state
    dp = {(0, 0): []}

    for set_idx in range(total_sets):
        new_dp = {}
        is_fifth = (set_idx == total_sets - 1)

        for key, prev_choices in dp.items():
            pa, pb = key

            # Try all possible scores for this set
            for sa in range(min(30, a - pa + 1)):
                for sb in range(min(30, b - pb + 1)):
                    if a - pa - sa < 0 or b - pb - sb < 0:
                        continue

                    a_won = is_valid_winner(sa, sb, is_fifth)
                    b_won = is_valid_5th_winner(sb, sa) if is_fifth else is_valid_winner(sb, sa, is_fifth)

                    if is_fifth and not (is_valid_5th_winner(sa, sb) or is_valid_5th_winner(sb, sa)):
                        continue

                    if is_fifth and (is_valid_5th_winner(sa, sb) == b_won):
                        next_key = (pa + sa, pb + sb)
                        if next_key not in new_dp:
                            new_dp[next_key] = []
                        new_dp[next_key].append((sa, sb))
                    elif is_valid_winner(sa, sb):
                        if remaining_a > 0:
                            next_key = (pa + sa, pb + sb)
                            if next_key not in new_dp:
                                new_dp[next_key] = []
                            new_dp[next_key].append((sa, sb))
                        remaining_a -= 1
                    elif is_valid_winner(sb, sa) and remaining_b > 0:
                        next_key = (pa + sa, pb + sb)
                        if next_key not in new_dp:
                            new_dp[next_key] = []
                        new_dp[next_key].append((sa, sb))
                        remaining_b -= 1

    # Check if we can reach exact (a, b)
    if (a, b) in new_dp:
        # Work backward to find path
        reconstructed = []
        current = (a, b)

        for set_idx in range(total_sets - 1, -1, -1):
            choices = new_dp.get(current, [])
            if not choices:
                return None
            sa, sb = choices[-1]
            reconstructed.append((sa, sb))
            current = (current[0] - sa, current[1] - sb)

        return reconstructed[::-1]

    return None
