def solve_volleyball(a, b):
    """
    Find best match score for teams with total points (a, b).
    """
    # Try outcomes in order of best score for Team A
    outcomes = [(3, 0), (3, 1), (3, 2), (1, 2), (2, 3), (0, 3)]

    for wA, wB in outcomes:
        sequences = generate_sequences(a, b, wA, wB)
        if sequences:
            return f"{wA}:{wB}\n" + " ".join(f"{x}:{y}" for x, y in sequences[0]) + " "

    return "Impossible"


def is_valid_set(sa, sb, is_last):
    """Check if (sa, sb) is a valid set score"""
    if is_last:
        return sa >= 15 and (sa - sb) >= 2 or sb >= 15 and (sb - sa) >= 2
    return sa >= 25 and (sa - sb) >= 2 or sb >= 25 and (sb - sa) >= 2


def generate_sequences(a, b, wA, wB):
    """Generate all valid set sequences for matching wA:wB score"""
    total = wA + wB
    if total > 5:
        return None

    from collections import defaultdict

    dp = {(0, 0): []}

    for i in range(total):
        new_dp = defaultdict(list)
        is_last = (i == total - 1)

        for (pa, pb), seqs in dp.items():
            for sa in range(27):
                for sb in range(27):
                    if pa + sa > a or pb + sb > b:
                        continue

                    if not is_valid_set(sa, sb, is_last):
                        continue

                    if (pa + sa, pb + sb) in new_dp:
                        new_dp[(pa + sa, pb + sb)].append((sa, sb))
                    else:
                        new_dp[(pa + sa, pb + sb)].append((sa, sb))

        dp = new_dp

    if (a, b) in dp:
        return dp[(a, b)]
    return None
